CREATE TABLE IF NOT EXISTS owner (id VARCHAR(36) PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, pw_hash VARCHAR(255) NOT NULL, revision BIGINT NOT NULL DEFAULT 0, subject_id VARCHAR(32) NOT NULL, workspace_id VARCHAR(32) NOT NULL, generation VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(36) PRIMARY KEY, token_hash VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, created BIGINT NOT NULL, expires BIGINT NOT NULL, last_seen BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS records (kind VARCHAR(20) NOT NULL, id VARCHAR(100) NOT NULL, revision BIGINT NOT NULL, deleted INTEGER NOT NULL, box TEXT NOT NULL, size INTEGER NOT NULL, updated BIGINT NOT NULL, PRIMARY KEY (kind,id));
CREATE TABLE IF NOT EXISTS operations (id VARCHAR(36) PRIMARY KEY, request_hash VARCHAR(64) NOT NULL, box TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS limits (bucket VARCHAR(64) PRIMARY KEY, started BIGINT NOT NULL, hits INTEGER NOT NULL);
